"""stages.contract: generated by the graph.py split (P1)."""

from __future__ import annotations

import json

from .. import isa, prompts
from ..flow import ladder, outcome
from ..isa import IsaLintError
from ..prompts import SYSTEM_PROMPT
from ..runtime.llm import DEFAULT_MAX_TOOL_ROUNDS
from ..runtime import llm_step, parsing, stage_services
from ..stages import fallbacks, feedback as feedback_mod
from ..stages.implement import intrinsics
from ..state import CfuDesignState


def _tool_rounds(state: CfuDesignState) -> int:
    return int(state.get("max_tool_rounds", DEFAULT_MAX_TOOL_ROUNDS) or DEFAULT_MAX_TOOL_ROUNDS)


def _contract_evidence_paths(state: CfuDesignState) -> list[tuple[str, str]]:
    """Artifacts the contract stage may read instead of receiving their bodies."""
    run_root = str(state.get("run_root", "") or "").rstrip("/")
    paths: list[tuple[str, str]] = [
        ("agents/specs/cfu_isa_template.yaml", "ISA contract template"),
    ]
    if run_root:
        paths.extend(stage_services.existing_evidence(state, [
            (f"{run_root}/07_analysis/workload_analysis.yaml", "prior workload analysis (carry its Roofline conclusion)"),
            (f"{run_root}/02_workload/workload_spec.yaml", "normalized WorkloadSpec"),
            # Only a repair/extension round has a contract to replace.
            (f"{run_root}/08_isa/cfu_isa.yaml", "the contract this call replaces"),
        ]))
    return paths


def _isa_step(state, client, tools_enabled, stage, label, prompt, fallback):
    """One ISA-authored answer: tool loop when available, plain call otherwise."""
    if tools_enabled:
        toolbox = stage_services._toolbox_for_stage(state, "isa")
        result, raw, _calls = llm_step._run_agent_step(
            state,
            toolbox,
            stage=stage,
            label=label,
            artifact_stage="isa",
            tool_calls_relpath="08_isa/isa_tool_calls.yaml",
            system=SYSTEM_PROMPT,
            user=prompt,
            fallback=fallback,
            client=client,
            response_format={"type": "json_object"},
            deliverable_hint="one YAML mapping (or exactly ABSTAIN when there is no CFU opportunity)",
        )
        return result, raw
    return llm_step._complete_llm(
        state,
        stage,
        label,
        SYSTEM_PROMPT,
        prompt,
        fallback,
        response_format={"type": "json_object"},
    )


def _contract_disabled(state: CfuDesignState, node: str) -> CfuDesignState | None:
    """Ablation (--no-isa-contract): no contract is ever authored here.

    The graph shape is unchanged (this node still runs and stamps the ``isa``
    gate), but the gate is recorded as disabled instead of validated, so the
    completeness machinery excludes it. Implement owns everything instead: the
    agent writes ``cfu_intrinsics.h`` itself from the intrinsic template.
    """
    if state.get("isa_contract", True):
        return None
    artifacts = stage_services._artifacts_for_stage(state, "isa")
    artifacts.write_yaml("isa", "08_isa/cfu_isa.yaml",
                         {"disabled": "no-isa-contract",
                          "note": "contract stage skipped by ablation; the agent authors cfu_intrinsics.h"},
                         status="disabled")
    artifacts.write_yaml("isa", "08_isa/validation.yaml", {"status": "disabled", "problems": []})
    return {
        "isa_spec": {}, "isa_spec_text": "", "design_contract": "",
        "isa_spec_errors": [], "isa_revision": 0, "stage_jobs": "implementation",
        **outcome.stage_result(
            state, rung="isa", ok=False, skipped=True, disabled="no-isa-contract",
            reason="disabled by --no-isa-contract (ablation)", next="implement",
            history=f"{node} skipped (--no-isa-contract): the agent authors "
                    "cfu_intrinsics.h itself from the intrinsic template.",
        ),
    }


def design_contract(state: CfuDesignState) -> CfuDesignState:
    disabled = _contract_disabled(state, "The ISA contract stage")
    if disabled is not None:
        return disabled
    spec = state.get("workload_spec", {})
    fallback = _isa_from_template(state.get("isa_spec_text", ""), spec, state.get("workload_analysis", ""))
    fallback_text = json.dumps(fallback, ensure_ascii=True, indent=2)
    client = llm_step._llm(state)
    tools_enabled = llm_step._tools_enabled(state, client)
    prompt = prompts.contract_prompt(
        state["task"],
        spec,
        state.get("workload_analysis", ""),
        state.get("context", {}),
        profile=state.get("embench_profiles"),
        feedback=feedback_mod.isa_repair_feedback(state) + feedback_mod.upstream_repair_feedback(state),
        agent_tools=tools_enabled,
        tool_rounds=_tool_rounds(state),
        artifact_paths=_contract_evidence_paths(state),
    )
    result, raw_output = _isa_step(
        state, client, tools_enabled, "design_contract", "isa", prompt, fallback_text
    )
    if result.text.strip().upper() == "ABSTAIN":
        stage_services._write_isa_artifact(state, {}, ["agent abstained: no worthwhile CFU opportunity"])
        return {
            "isa_spec": {}, "isa_spec_text": "", "design_contract": result.text,
            "isa_spec_errors": [], "llm_raw_outputs": [raw_output],
            "status": "blocked", "termination_reason": "ABSTAIN", "stage_jobs": "review",
            **outcome.stage_result(state, rung="isa", ok=False, abstain=True,
                                   reason="agent selected ABSTAIN", next="review_and_route",
                                   history="Agent abstained from CFU design."),
        }
    try:
        isa_spec, problems = isa.validate_isa_text(result.text)
    except IsaLintError as exc:
        isa_spec, problems = {}, [f"ISA output is invalid: {exc}"]
    if not problems and not _has_isaable_commands(isa_spec):
        problems = ["no usable commands after ISA extraction"]
    if problems:
        # Show what the parser actually saw, not only the resulting symptoms.
        problems = [*problems, feedback_mod._isa_shape_note(isa_spec)]
    stage_services._write_isa_artifact(state, isa_spec, problems)
    ok = not problems
    extra, next_node = ladder._ladder_transition(
        state,
        "isa",
        ok=ok,
        default="implement",
        repair_target="design_contract",
    )
    history = "Produced CFU ISA/integration contract."
    if feedback_mod._isa_enveloped(result.text):
        history += " (unwrapped from a model envelope)"
    update = {
        "isa_spec": isa_spec,
        "isa_revision": 0,
        "isa_spec_text": parsing._yaml_str(isa_spec),
        "isa_spec_errors": problems,
        "design_contract": result.text,
        "llm_raw_outputs": [raw_output],
        "stage_jobs": "implementation",
        **outcome.stage_result(state, rung="isa", ok=ok, problems=problems, next=next_node,
                               history=history),
    }
    return ladder._apply_transition(update, extra)


def extend_isa(state: CfuDesignState) -> CfuDesignState:
    """Append commands without replacing the incumbent contract on rejection."""
    disabled = _contract_disabled(state, "The ISA extension round")
    if disabled is not None:
        return disabled
    previous = state.get("isa_extension_base") or state.get("isa_spec", {})
    feedback = feedback_mod.isa_repair_feedback(state)
    client = llm_step._llm(state)
    tools_enabled = llm_step._tools_enabled(state, client)
    run_root = str(state.get("run_root", "") or "").rstrip("/")
    if tools_enabled and run_root:
        incumbent_block = (
            "Incumbent contract (reuse complete hash-matched Run memory, otherwise read it "
            "before extending; every existing command must be kept):\n"
            f"- {run_root}/08_isa/cfu_isa.yaml"
        )
    else:
        incumbent_block = f"Incumbent contract:\n{parsing._yaml_str(previous)}"
    prompt = prompts.contract_prompt(
        state["task"], state.get("workload_spec", {}),
        state.get("workload_analysis", ""), state.get("context", {}),
        profile=state.get("embench_profiles"), feedback=feedback,
        agent_tools=tools_enabled,
        tool_rounds=_tool_rounds(state),
        artifact_paths=_contract_evidence_paths(state),
    ) + (
        "\n=== APPEND-ONLY ISA EXTENSION ===\n"
        "Return the COMPLETE candidate contract, preserving every existing command, "
        "encoding, operand/result semantic and shared state/memory/datapath/integration/assumptions "
        "and software ABI contract (only intrinsic_names may grow). "
        "Append at least one useful command with a unique (function_id, subfunction_id). "
        "subfunction_id is funct7 (0..127), default 0; function_id stays funct3 (0..7). "
        "Old command names cannot be reassigned. New control operations must obey the "
        "existing state/reset contract. The next rungs implement hardware AND software "
        "that calls the new operation, then validate correctness and measure cost/cycles.\n"
        f"Optimization proposal: {(state.get('optimization_plan') or {}).get('reason', '')}\n"
        + incumbent_block
    )
    result, raw = _isa_step(
        state, client, tools_enabled, "extend_isa", "isa_extension", prompt, parsing._yaml_str(previous)
    )
    try:
        candidate, problems = isa.validate_isa_text(result.text)
        if not problems:
            problems = isa.validate_isa_extension(previous, candidate)
    except (IsaLintError, TypeError, AttributeError) as exc:
        candidate, problems = previous, [f"ISA extension rejected: {exc}"]
    if problems:
        problems = [*problems, feedback_mod._isa_shape_note(candidate)]
    ok = not problems and bool(result.used_llm)
    if not result.used_llm:
        problems = [*problems, "ISA extension requires a model-authored candidate"]
    extra, next_node = ladder._ladder_transition(
        state, "isa", ok=ok, default="implement", repair_target="extend_isa",
    )
    revision = int(state.get("isa_revision", 0)) + (1 if ok else 0)
    artifacts = stage_services._artifacts_for_stage(state, "isa")
    artifacts.write_yaml("isa", f"08_isa/extensions/attempt_{len(state.get('llm_raw_outputs', [])):03d}.yaml",
                         {"candidate": candidate, "problems": problems, "accepted": ok,
                          "base_hash": intrinsics._isa_digest({"isa_spec": previous}), "revision": revision})
    update = {
        "isa_extension_base": previous, "isa_spec_errors": problems,
        "llm_raw_outputs": [raw],
        **outcome.stage_result(state, rung="isa", ok=ok, problems=problems, next=next_node,
                               revision=revision,
                               history=f"ISA extension {'accepted' if ok else 'rejected'} (revision {revision})."),
    }
    if ok:
        stage_services._write_isa_artifact(state, candidate, [])
        artifacts = stage_services._artifacts_for_stage(state, "isa")
        artifacts.write_yaml("isa", f"08_isa/revisions/{revision:03d}.yaml", candidate)
        update.update(isa_spec=candidate, isa_spec_text=parsing._yaml_str(candidate),
                      design_contract=parsing._yaml_str(candidate), isa_revision=revision,
                      isa_added_symbols=sorted(set(isa.intrinsic_symbols(candidate)) - set(isa.intrinsic_symbols(previous))),
                      stage_jobs="implement")
    return ladder._apply_transition(update, extra)


def _isa_from_template(template: str, spec: dict, analysis: str) -> dict:
    try:
        template_data = parsing.parse_yaml_mapping(template) or {}
    except Exception:
        template_data = {}
    operation = spec.get("operation", "unknown")
    analysis_data = parsing.parse_yaml_mapping(analysis) or {}
    roofline = analysis_data.get("roofline")
    if not isinstance(roofline, dict):
        roofline = fallbacks.deterministic_roofline_analysis(spec)
    commands = [
        {
            "function_id": i, "name": f"op_{i}", "operand": "CPU rs1/rs2 values",
            "result": "CPU rd", "semantics": f"{operation} step {i}", "response": "value",
            "resources": [
                {"storage": "cpu", "access": "read", "role": "rs1"},
                {"storage": "cpu", "access": "read", "role": "rs2"},
                {"storage": "cpu", "access": "write", "role": "rd"},
            ],
        }
        for i in range(1, 4)
    ]
    return {
        "spec_version": "1",
        "identity": {
            "name": f"{operation}_cfu",
            "status": "draft",
            "opcode": "custom0 (0x0B)",
            "function_id_width": 3,
            "reference_workload": spec.get("name", operation),
        },
        "commands": commands,
        "operations_contract": {"pattern": spec.get("pattern", "")},
        "roofline": roofline,
        "state": template_data.get("state", {}),
        "memory": {"operator_owned": False, "load": True, "store": False},
        # Keep fallback datapath metadata conservative. These are independent
        # optional knobs; do not invent algorithm-specific dimensions.
        "datapath": {
            "vlen": 0,
            "xlen": 0,
            "regDepth": 0,
            "implementation": {},
        },
        "software": {"intrinsics_header": "cfu_intrinsics.h", "scalar_fallback": True},
        "integration": {
            "hardware_component": "AgentCfu",
            "hardware_fiber": "AgentCfuFiber",
            "bus_style": "CfuBus + optional TileLink",
            "soc_cli_flags": ["--mico-agent-cfu"],
            "single_cpu_bus_owner": True,
        },
        "validation": {
            "status": "draft",
            "scalar_reference": True,
            "soc_simulation": False,
            "cycle_profile": True,
            "yosys_cost": True,
            "requirements": [analysis] if analysis and isinstance(analysis, str) else ["Scalar reference must match the CFU output."],
        },
        "assumptions": {},
        "unknowns": spec.get("unknowns", []),
    }


def _has_isaable_commands(isa_spec: dict) -> bool:
    commands = isa_spec.get("commands")
    return isinstance(commands, list) and bool(commands) and all(isinstance(item, dict) for item in commands)
